class compareProductsSelect extends HTMLElement{constructor(){super(),this.customSelect=this.querySelector("custom-select"),this.customSelectInput=this.customSelect.querySelector("input[data-custom-select-input]"),this.oldNames=this.customSelect.querySelectorAll(".form-select__dropdown-option"),this.newNames=this.querySelectorAll(".compare-products-section__new-name"),this.imagesPairs=this.querySelectorAll(".compare-products-section__image-item"),this.eventListeners()}eventListeners(){this.customSelectInput.addEventListener("change",()=>{this.oldNames.forEach((e,t)=>{JSON.parse(e.getAttribute("aria-selected"))&&this.toggleNamesAndImages(t)})})}toggleNamesAndImages(s){this.newNames.forEach((e,t)=>{e.setAttribute("aria-hidden",!0),t===s&&e.setAttribute("aria-hidden",!1)}),this.imagesPairs.forEach((e,t)=>{e.setAttribute("aria-hidden",!0),t===s&&e.setAttribute("aria-hidden",!1)})}}customElements.define("compare-products-select",compareProductsSelect);